if(!obterTokenCliente())location.href='login.html';const cks=[...document.querySelectorAll('.cartao-conta input[type=checkbox]')];try{const g=JSON.parse(localStorage.getItem('lumina_notif')||'null');if(g)cks.forEach((c,i)=>c.checked=!!g[i])}catch{}document.getElementById('nt-guardar').onclick=()=>{localStorage.setItem('lumina_notif',JSON.stringify(cks.map(c=>c.checked)));document.getElementById('nt-msg').textContent='Guardado neste dispositivo.'}
